const N8N_URL = 'http://n8n-jeet.duckdns.org:5678';
const API_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiJlZDUwYTUwNy1kOTNkLTQ1YzMtOTQxMi1kODBiYWJiODFkZDAiLCJpc3MiOiJuOG4iLCJhdWQiOiJwdWJsaWMtYXBpIiwiaWF0IjoxNzcxMjIzOTM0fQ.OX7lYlEY7jTxoXTjPLrCED_v6l1T-02MxyqFexLik5s';

const now = new Date();
const nowMs = now.getTime();
const helpers = this.helpers;

const scheduled = [
  { id: 'gMTOpnDfuO3g5tyb', name: 'Daily Ops', staleH: 26 },
  { id: '9u2JEpZGK81jkCXP', name: 'Prospect Finder', staleH: 26 },
  { id: 'jOhzPZTA86SexCXp', name: 'Outreach Automation', staleH: 26 },
  { id: 'KYSdsLXV50H7MHGr', name: 'Sales Pipeline', staleH: 26 },
  { id: 'hgF70RKYIUyQ57Ng', name: 'Client Comms', staleH: 14 },
  { id: 'teKN5R6r86kUXjgD', name: 'LinkedIn Brand', staleH: 26 },
  { id: 'rtmRq6ttmgxVH5bx', name: 'Vibe5 Prospecting', staleH: 26 },
  { id: 'BU38fTuYLPvm0adI', name: 'Creator Outreach', staleH: 26 },
  { id: 'DZbFqt2WtxlXtXl1', name: 'Performance Sync', staleH: 8 },
  { id: 'AZXaFe3cNDhCS7uQ', name: 'Comment Watch', staleH: 0.75 },
  { id: 'zKaI0jdgELg0x1WQ', name: 'Ad Library Scanner', staleH: 80 },
  { id: 'aKNHRB0Fxa5o3xyC', name: 'Reporting', staleH: 180 },
  { id: 'DUfrRerxOinES9Cf', name: 'Orchestrator v2', staleH: 0.25 },
];

const webhookOnly = [
  { id: 'RLi-u9gL1aQ7Bl37TSidA', name: 'Phase 1 Research' },
  { id: 'U2bxLckriORGZIyU', name: 'Phase 2 Approval' },
  { id: 'iZOxbVl1X2w74Pzi', name: 'Phase 3 Scripts' },
  { id: 'hvytJvFSc6ZuNMAc', name: 'Phase 4 Delivery' },
  { id: 'XNdHsZnLclh1pARm', name: 'Script Agent' },
  { id: 'tuewOOpK3V8I4uZX', name: 'Script Revision' },
  { id: '8HDjMAgRTa5tcaQG', name: 'Creator Scout' },
  { id: 'ZJfWCoCYf9c0O8tdywMTj', name: 'Onboarding' },
  { id: '0A0iVv9qLmAnRneW', name: 'Calendar Connector' },
  { id: 'WUPK5D8u3Ge40WRF', name: 'Content Repurposing' },
  { id: 'SdnCREsCQovnF56R', name: 'Creative Tear-Down' },
  { id: 'ysSIAB5jGbXkHHda', name: 'Brand Voice DNA' },
];

const issues = [];
let healthyCount = 0;
const perWorkflow = [];

function timeAgo(ms) {
  const h = Math.floor(ms / 3600000);
  const m = Math.floor((ms % 3600000) / 60000);
  if (h > 48) return Math.floor(h / 24) + 'd ago';
  if (h > 0) return h + 'h ' + m + 'm ago';
  return m + 'm ago';
}

for (const wf of scheduled) {
  let execs = null;
  try {
    const resp = await helpers.httpRequest({
      method: 'GET',
      url: N8N_URL + '/api/v1/executions?workflowId=' + encodeURIComponent(wf.id) + '&limit=5&status=error,success',
      headers: { 'X-N8N-API-KEY': API_KEY },
      json: true,
    });
    execs = resp.data || [];
  } catch (e) {
    execs = null;
  }
  await new Promise(r => setTimeout(r, 200));

  if (execs === null) {
    issues.push({ name: wf.name, status: 'API_ERROR', detail: 'Could not fetch executions' });
    perWorkflow.push({ name: wf.name, status: 'api_error' });
    continue;
  }
  if (execs.length === 0) {
    issues.push({ name: wf.name, status: 'NEVER_RAN', detail: 'No executions found (may be deactivated)' });
    perWorkflow.push({ name: wf.name, status: 'never_ran' });
    continue;
  }

  const last = execs[0];
  const lastTime = new Date(last.stoppedAt || last.startedAt).getTime();
  const ageMsec = nowMs - lastTime;
  const ageStr = timeAgo(ageMsec);
  const staleMs = wf.staleH * 3600000;

  if (last.status === 'error') {
    const errMsg = (last.data && last.data.resultData && last.data.resultData.error && last.data.resultData.error.message) || 'Unknown error';
    issues.push({ name: wf.name, status: 'ERROR', detail: 'Last ran: ' + ageStr + '\nError: ' + errMsg.substring(0, 200) });
    perWorkflow.push({ name: wf.name, status: 'error', lastRan: ageStr, error: errMsg.substring(0, 200) });
  } else if (ageMsec > staleMs) {
    issues.push({ name: wf.name, status: 'STALE', detail: 'Last ran: ' + ageStr + ' (expected every ' + wf.staleH + 'h)\nLast status: ' + last.status });
    perWorkflow.push({ name: wf.name, status: 'stale', lastRan: ageStr });
  } else {
    healthyCount++;
    perWorkflow.push({ name: wf.name, status: 'healthy', lastRan: ageStr });
  }
}

for (const wf of webhookOnly) {
  let execs = null;
  try {
    const resp = await helpers.httpRequest({
      method: 'GET',
      url: N8N_URL + '/api/v1/executions?workflowId=' + encodeURIComponent(wf.id) + '&limit=5&status=error,success',
      headers: { 'X-N8N-API-KEY': API_KEY },
      json: true,
    });
    execs = resp.data || [];
  } catch (e) {
    execs = null;
  }
  await new Promise(r => setTimeout(r, 200));

  if (execs === null) {
    issues.push({ name: wf.name, status: 'API_ERROR', detail: 'Could not fetch executions' });
    perWorkflow.push({ name: wf.name, status: 'api_error' });
    continue;
  }

  const dayAgo = nowMs - 86400000;
  const recentErrors = execs.filter(e => {
    const t = new Date(e.stoppedAt || e.startedAt).getTime();
    return e.status === 'error' && t > dayAgo;
  });

  if (recentErrors.length > 0) {
    const last = recentErrors[0];
    const lastTime = new Date(last.stoppedAt || last.startedAt).getTime();
    const ageStr = timeAgo(nowMs - lastTime);
    const errMsg = (last.data && last.data.resultData && last.data.resultData.error && last.data.resultData.error.message) || 'Unknown error';
    issues.push({ name: wf.name, status: 'ERROR', detail: 'Last error: ' + ageStr + ' (' + recentErrors.length + ' errors in 24h)\nError: ' + errMsg.substring(0, 200) });
    perWorkflow.push({ name: wf.name, status: 'error', lastRan: ageStr, recentErrors: recentErrors.length, error: errMsg.substring(0, 200) });
  } else {
    healthyCount++;
    perWorkflow.push({ name: wf.name, status: 'healthy' });
  }
}

const total = scheduled.length + webhookOnly.length;
const dateStr = now.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
let msg = '';

if (issues.length === 0) {
  msg = ':white_check_mark: *Workflow Health Monitor \u2014 ' + dateStr + '*\n\n';
  msg += 'All ' + total + ' workflows healthy.\n\n';
  msg += '*Scheduled (' + scheduled.length + '):* All ran on time\n';
  msg += '*Webhook (' + webhookOnly.length + '):* No errors in last 24h\n\n';
  msg += '_Next check: tomorrow 12:30 PM IST_';
} else {
  msg = ':rotating_light: *Workflow Health Monitor \u2014 ' + dateStr + '*\n\n';
  msg += healthyCount + '/' + total + ' workflows healthy | *' + issues.length + ' issue' + (issues.length > 1 ? 's' : '') + ' found*\n\n';
  for (const issue of issues) {
    const icon = issue.status === 'ERROR' ? ':x:' : (issue.status === 'STALE' ? ':warning:' : ':grey_question:');
    msg += icon + ' *' + issue.name + '* \u2014 ' + issue.status + '\n';
    const lines = issue.detail.split('\n');
    for (const line of lines) {
      msg += '   ' + line + '\n';
    }
    msg += '\n';
  }
  msg += '_Check n8n UI: http://n8n-jeet.duckdns.org:5678_';
}

return [{
  json: {
    slackMsg: msg,
    hasIssues: issues.length > 0,
    healthyCount: healthyCount,
    issueCount: issues.length,
    total: total,
    issues: issues,
    perWorkflow: perWorkflow,
    severity: issues.length > 0 ? 'warning' : 'info',
    timestamp: now.toISOString(),
  }
}];
